<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script>
(function(){const d=@json($chartData);if(!window.Chart)return;const colors=['#087b45','#1685dc','#e5ac17','#8055cf','#ed658c','#16a6a0'];function plot(id,type,labels,datasets){new Chart(document.getElementById(id),{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},...(type==='doughnut'?{}:{scales:{y:{beginAtZero:true,ticks:{precision:0}}}})}})}function series(rows){return rows.map((r,i)=>({label:r.label,data:r.data,backgroundColor:colors[i%colors.length],borderColor:colors[i%colors.length],tension:.25}))}plot('admMonths','bar',d.labels,series(d.series));plot('admTrend','line',d.labels,series(d.trend));for(const [id,obj] of [['admSource',d.source],['admClass',d.classes]])plot(id,'doughnut',Object.keys(obj),[{data:Object.values(obj),backgroundColor:colors}]);})();
</script>
